import {mountManufacturing} from './workbench.mjs';
import fixture from './fixture.mjs';
const read=new Set(['mfg_inspect_v1','mfg_material_requirements_v1','mfg_recipe_substitutions_v1','mfg_preview_substitution_v1','mfg_preview_substitution_v2','mfg_master_validation_v1','mfg_material_waste_report_v1']);
mountManufacturing(document.getElementById('manufacturing'),{synthetic:true,context:{tenant_id:951,business_id:9511,site_id:9521,label:'Fictional QA — recorded synthetic snapshot'},rpc:async(name,args)=>{const k=name+'|'+JSON.stringify(args,Object.keys(args).sort());if(!read.has(name)||!Object.hasOwn(fixture,k))return {error:{message:'NOT_CONNECTED — offline preview, no writes or live RPC'}};return {data:JSON.parse(JSON.stringify(fixture[k])),error:null};}});
